"""Regenerate docs/SOURCES.md from the catalog (the catalog is the source of truth)."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))


from app.providers.catalog import PRIMARY_SOURCES, REFERENCE_SOURCES

out = ["# Source-to-metric mapping", "",
       "Generated by `python scripts/gen_sources_doc.py` from `app/providers/catalog.py`. Do not edit by hand.", "",
       "Relevance is the default `source_relevance_score`; `0` means the source can never move the BTC score.",
       "Reliability starts at the listed base and is scaled live by each adapter's recent success rate.", "",
       "Access: **free** = official public API, no key · **key**/**paid** = configurable via env · "
       "**no_api** = nothing to integrate legally/technically · **blocked** = public page refuses automation.", "",
       "## The 40 reference sources", "",
       "| # | Source | Tier | BTC relevance | Score | Access | Adapter | Metrics → engines | Notes |",
       "|---|---|---|---|---|---|---|---|---|"]
for s in REFERENCE_SOURCES:
    m = ", ".join(s.metrics) or "—"
    e = ", ".join(s.engines) or "—"
    out.append(f"| {s.number} | [{s.name}]({s.url}) | {s.tier} | {s.btc_relevance} | {s.relevance} | {s.access} | "
               f"{s.adapter or '—'} | {m} → {e} | {s.official_api}. {s.notes} |")
out += ["", "## Primary-data providers", "",
        "CoinGlass, Velo and CoinAnk aggregate these same exchange APIs; reading them directly is free and auditable.", "",
        "| Provider | Tier | Score | Base reliability | Metrics | Engines | Notes |", "|---|---|---|---|---|---|---|"]
for s in PRIMARY_SOURCES:
    out.append(f"| {s.name} (`{s.adapter}`) | {s.tier} | {s.relevance} | {s.base_reliability} | {', '.join(s.metrics)} | "
               f"{', '.join(s.engines)} | {s.official_api}. {s.notes} |")
ref = REFERENCE_SOURCES
out += ["", "## Summary", "",
        f"- Reference sources with an adapter: {sum(1 for s in ref if s.adapter)} / 40",
        f"- Free, no key needed: {', '.join(s.name for s in ref if s.access == 'free' and s.adapter)}",
        f"- Key/paid adapters implemented (unverified until a key is supplied): "
        f"{', '.join(s.name for s in ref if s.access in ('key', 'paid') and s.adapter)}",
        f"- Directional weight 0 by design: {', '.join(s.name for s in ref if s.relevance == 0)}", ""]
Path(__file__).resolve().parents[2].joinpath("docs", "SOURCES.md").write_text("\n".join(out), encoding="utf-8")
print("wrote docs/SOURCES.md")
